import csv
import io


def convert_csv_encoding(data, from_encoding, to_encoding, delimiter):
    text = data.decode(from_encoding)

    reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)
    records = list(reader)

    if not records:
        return [], b""

    headers = records[0]
    rows = [
        {
            header: row[i] if i < len(row) else ""
            for i, header in enumerate(headers)
        }
        for row in records[1:]
    ]

    output = io.StringIO(newline="")
    writer = csv.writer(output, delimiter=delimiter, lineterminator="\n")
    writer.writerows(records)

    return rows, output.getvalue().encode(to_encoding)
```

```python
import csv
import io


def convert_csv_encoding(data, from_encoding, to_encoding, delimiter):
    text = data.decode(from_encoding)

    source = io.StringIO(text, newline="")
    reader = csv.reader(source, delimiter=delimiter)

    output = io.StringIO(newline="")
    writer = csv.writer(output, delimiter=delimiter, lineterminator="\n")

    try:
        headers = next(reader)
    except StopIteration:
        return [], b""

    writer.writerow(headers)
    rows = []

    for values in reader:
        rows.append({
            header: values[i] if i < len(values) else ""
            for i, header in enumerate(headers)
        })
        writer.writerow(values)

    return rows, output.getvalue().encode(to_encoding)
```

The output uses `\n` line endings; CSV quoting may be normalized when the rows are written back.

