from collections import Counter

def emp_age_stats(ages_by_department):
    ages = ages_by_department.get("EMP$$", [])
    if not ages:
        return (0, 0, [])

    ordered = sorted(ages)
    mean = sum(ages) / len(ages)
    n = len(ordered)

    if n % 2:
        median = ordered[n // 2]
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2

    counts = Counter(ages)
    highest_frequency = max(counts.values())
    modes = sorted(age for age, count in counts.items()
                   if count == highest_frequency)

    return (mean, median, modes)
```

