from numbers import Real

def analyze_column_against_mean(data, column, value):
    if column not in data:
        raise ValueError(f"Column {column!r} is not in data")
    if isinstance(value, bool) or not isinstance(value, Real):
        raise ValueError("value must be a number")

    values = data[column]
    if not values:
        return ([], 0)

    mean = sum(values) / len(values)
    above_mean = [item for item in values if item > mean]
    count = sum(item > value for item in values)

    return above_mean, count
