import csv
import io

def top_selling_product(csv_text):
    reader = csv.DictReader(io.StringIO(csv_text))

    if not reader.fieldnames or not {"product", "quantity"}.issubset(reader.fieldnames):
        raise ValueError("CSV must have 'product' and 'quantity' columns")

    totals = {}
    for row in reader:
        try:
            quantity = int(row["quantity"])
        except (TypeError, ValueError):
            raise ValueError("Quantity must be a valid integer") from None

        product = row["product"]
        totals[product] = totals.get(product, 0) + quantity

    if not totals:
        raise ValueError("CSV has no data rows")

    # If totals tie, returns the product that appeared first.
    return max(totals, key=totals.get)
