import json
import re

_EMAIL_RE = re.compile(r"[^@\s]+@[^@\s]+\.[^@\s]+")


def clean_json_record(json_str):
    obj = json.loads(json_str)
    data = {}
    counts = {}

    for key, value in obj.items():
        if value is None:
            continue

        if isinstance(value, str) and _EMAIL_RE.fullmatch(value):
            value = "None"

        data[key] = value
        counts[value] = counts.get(value, 0) + 1

    return {"data": data, "counts": counts}
```

The dictionaries retain the input key order. `counts` uses the cleaned values as its keys.

