def count_urls_in_json(json_str, top_n=10):
    """Count URL-like string values in JSON, returning the top_n most frequent."""
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n < 0:
        raise ValueError("top_n must be a non-negative integer")

    data = json.loads(json_str)  # Raises ValueError for invalid JSON.

    def url_values(value):
        if isinstance(value, dict):
            for child in value.values():
                yield from url_values(child)
        elif isinstance(value, list):
            for child in value:
                yield from url_values(child)
        elif isinstance(value, str) and value.startswith(("http://", "https://", "www.")):
            yield value

    return dict(Counter(url_values(data)).most_common(top_n))
