import hmac


def verify_hmac_sha1(message_b64, signature, secret_key):
    try:
        message = base64.b64decode(message_b64, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("message_b64 must be valid base64") from exc

    expected = hmac.new(
        secret_key.encode("utf-8"),
        message,
        hashlib.sha1,
    ).hexdigest()

    try:
        supplied = signature.encode("ascii")
    except (AttributeError, UnicodeEncodeError):
        return False

    return hmac.compare_digest(expected.encode("ascii"), supplied)
