        message,
        hashlib.sha1,
    ).hexdigest()

    if not isinstance(signature, str):
        return False

    try:
        signature_bytes = signature.encode("ascii")
    except UnicodeEncodeError:
        return False

    return hmac.compare_digest(expected.encode("ascii"), signature_bytes)
