import ast


def _matching_brace(text, start):
    """Return the index after the matching } for text[start], or None."""
    depth = 0
    i = start
    n = len(text)

    while i < n:
        ch = text[i]

        if ch == "#":  # A comment ends at the newline.
            newline = text.find("\n", i)
            i = n if newline == -1 else newline + 1
            continue

        if ch in ("'", '"'):
            quote = ch
            triple = text.startswith(ch * 3, i)
            delimiter = ch * 3 if triple else ch
            i += len(delimiter)

            while i < n:
                if text[i] == "\\":
                    i += 2
                elif text.startswith(delimiter, i):
                    i += len(delimiter)
                    break
                else:
                    i += 1
            continue

        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return i + 1

        i += 1

    return None


def extract_dicts(text):
    """Extract outermost Python dictionary literals from text."""
    result = []
    i = 0

    while i < len(text):
        if text[i] != "{":
            i += 1
            continue

        end = _matching_brace(text, i)
        if end is not None:
            candidate = text[i:end]
            try:
                value = ast.literal_eval(candidate)
            except (SyntaxError, ValueError):
                pass
            else:
                if isinstance(value, dict):
                    result.append(value)
                    i = end  # Skip nested dictionaries in this one.
                    continue

        i += 1

    return result
```

`ast.literal_eval` handles only Python literals, so this does not execute arbitrary code. A successfully parsed dictionary is skipped as a whole, ensuring nested dictionaries are not returned separately.

```python
import ast


def extract_dicts(text):
    # Find balanced {...} spans, ignoring braces inside strings and comments.
    spans = []
    stack = []
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if ch == "#":
            newline = text.find("\n", i)
            i = n if newline == -1 else newline + 1
            continue

        if ch in "'\"":
            # Quotes in ordinary words (for example, the apostrophe in "it's")
            # are not Python string delimiters.
            prefix_start = i
            while prefix_start > 0 and text[prefix_start - 1].isalpha():
                prefix_start -= 1
            prefix = text[prefix_start:i].lower()
            valid_prefix = prefix in {"", "r", "u", "b", "f", "br", "rb", "fr", "rf"}
            preceded_by_word_char = (
                prefix_start > 0
                and (text[prefix_start - 1].isalnum() or text[prefix_start - 1] == "_")
            )

            if not valid_prefix or preceded_by_word_char:
                i += 1
                continue

            quote = ch
            triple = text.startswith(quote * 3, i)
            delimiter = quote * (3 if triple else 1)
            j = i + len(delimiter)

            while j < n:
                if text[j] == "\\":
                    j += 2
                elif text.startswith(delimiter, j):
                    j += len(delimiter)
                    break
                elif not triple and text[j] == "\n":
                    break
                else:
                    j += 1

            # If the quote was unterminated, treat it as ordinary text and
            # continue scanning so later candidates can still be found.
            if j <= n and text[max(i, j - len(delimiter)):j] == delimiter:
                i = j
            else:
                i += 1
            continue

        if ch == "{":
            stack.append(i)
        elif ch == "}" and stack:
            start = stack.pop()
            spans.append((start, i + 1))

        i += 1

    # Keep only spans that parse as dictionaries.
    candidates = []
    for start, end in spans:
        try:
            value = ast.literal_eval(text[start:end])
        except (SyntaxError, ValueError, TypeError, RecursionError):
            continue
        if isinstance(value, dict):
            candidates.append((start, end, value))

    # Omit dictionaries nested inside another dictionary.
    result = []
    for start, end, value in sorted(candidates):
        if not any(
            outer_start < start and end < outer_end
            for outer_start, outer_end, _ in candidates
        ):
            result.append(value)

    return result
```

`ast.literal_eval` limits evaluation to Python literals rather than executing arbitrary code. Dictionaries inside lists or tuples are returned; dictionaries nested inside another dictionary are omitted.

