import ast


def _skip_string(text, i):
    """Return the position just after the quoted string starting at i."""
    quote = text[i]
    triple = text.startswith(quote * 3, i)
    delimiter = quote * (3 if triple else 1)
    j = i + len(delimiter)

    while j < len(text):
        if text[j] == "\\":
            j += 2
        elif text.startswith(delimiter, j):
            return j + len(delimiter)
        else:
            j += 1
    return len(text)


def _matching_brace(text, start):
    """Find the closing brace for the opening brace at start, or return None."""
    depth = 0
    i = start

    while i < len(text):
        char = text[i]

        if char in ("'", '"'):
            i = _skip_string(text, i)
        elif char == "#":
            newline = text.find("\n", i)
            i = len(text) if newline == -1 else newline + 1
        elif char == "{":
            depth += 1
            i += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return i
            i += 1
        else:
            i += 1

    return None


def extract_dicts(text):
    """Return outermost Python dictionary literals found in text."""
    result = []
    i = 0

    while i < len(text):
        char = text[i]

        if char in ("'", '"'):
            i = _skip_string(text, i)
        elif char == "#":
            newline = text.find("\n", i)
            i = len(text) if newline == -1 else newline + 1
        elif char == "{":
            end = _matching_brace(text, i)

            if end is not None:
                try:
                    value = ast.literal_eval(text[i:end + 1])
                except (SyntaxError, ValueError, TypeError):
                    pass
                else:
                    if isinstance(value, dict):
                        result.append(value)
                        i = end + 1
                        continue

            i += 1
        else:
            i += 1

    return result
