`ast.literal_eval` parses only Python literals; it does not execute code. When a dictionary is parsed successfully, the scan skips its contents, so nested dictionaries are not returned separately.

```python
import ast
import io
import tokenize


def extract_dicts(text):
    # Find balanced brace pairs while ignoring braces inside Python strings/comments.
    tokens = []
    try:
        for token in tokenize.generate_tokens(io.StringIO(text).readline):
            tokens.append(token)
    except (tokenize.TokenError, IndentationError):
        # Keep any tokens produced before malformed trailing text.
        pass

    lines = text.splitlines(keepends=True)
    line_offsets = [0]
    for line in lines:
        line_offsets.append(line_offsets[-1] + len(line))

    def offset(position):
        line, column = position
        return line_offsets[line - 1] + column

    stack = []
    pairs = []
    for token in tokens:
        if token.type == tokenize.OP and token.string == "{":
            stack.append(token.start)
        elif token.type == tokenize.OP and token.string == "}" and stack:
            start = stack.pop()
            pairs.append((offset(start), offset(token.end)))

    # Try larger, earlier candidates first, so a valid outer dict suppresses
    # any dictionaries nested inside it.
    pairs.sort()
    found = []

    for start, end in pairs:
        if any(a <= start and end <= b for a, b, _ in found):
            continue

        try:
            value = ast.literal_eval(text[start:end])
        except (SyntaxError, ValueError, TypeError, MemoryError, RecursionError):
            continue

        if isinstance(value, dict):
            found.append((start, end, value))

    return [value for _, _, value in found]
```

`ast.literal_eval` accepts Python literals without executing arbitrary code. If an outer candidate is not a valid literal, valid dictionaries inside it can still be returned.

