import ast


def _matching_brace(text, start):
    """Return the index after the matching }, or None if there isn't one."""
    depth = 0
    i = start

    while i < len(text):
        ch = text[i]

        # Skip quoted strings, including triple-quoted strings.
        if ch in ("'", '"'):
            delimiter = ch * (3 if text.startswith(ch * 3, i) else 1)
            i += len(delimiter)

            while i < len(text):
                if text[i] == "\\":
                    i += 2
                elif text.startswith(delimiter, i):
                    i += len(delimiter)
                    break
                else:
                    i += 1
            else:
                return None

            continue

        # Skip Python comments.
        if ch == "#":
            newline = text.find("\n", i)
            i = len(text) if newline == -1 else newline + 1
            continue

        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return i + 1

        i += 1

    return None


def extract_dicts(text):
    """Extract outermost dictionary literals from text, in order."""
    result = []
    i = 0

    while i < len(text):
        if text[i] != "{":
            i += 1
            continue

        end = _matching_brace(text, i)
        if end is not None:
            try:
                value = ast.literal_eval(text[i:end])
            except (SyntaxError, ValueError, TypeError, RecursionError):
                pass
            else:
                if isinstance(value, dict):
                    result.append(value)
                    i = end  # Skip nested dictionaries in this one.
                    continue

        i += 1

    return result
```

`ast.literal_eval` only evaluates Python literals; it does not execute arbitrary code. For example:

```python
extract_dicts("Data: {'a': 1} and {'b': {'c': 2}}")
# [{'a': 1}, {'b': {'c': 2}}]
```

