def most_common_letter_pair(word):
    letters = ''.join(ch.lower() for ch in word if ch.isalpha())

    if len(letters) < 2:
        return None

    counts = {}
    for i in range(len(letters) - 1):
        pair = letters[i:i + 2]
        counts[pair] = counts.get(pair, 0) + 1

    # max keeps the first pair encountered when counts tie.
    return max(counts.items(), key=lambda item: item[1])
```

