import binascii
import struct


def hex_to_float_utf8(hex_key):
    if not isinstance(hex_key, str) or len(hex_key) != 8:
        raise ValueError("expected exactly 8 hexadecimal characters")

    try:
        raw = binascii.unhexlify(hex_key)
    except (binascii.Error, UnicodeEncodeError) as exc:
        raise ValueError("invalid hexadecimal string") from exc

    value = struct.unpack(">f", raw)[0]
    return str(value).encode("utf-8")
```

