    for name, content in files.items():
        ascii_name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode("ascii")
        result[ascii_name] = {
            "Size": len(content),
            "MD5 Hash": hashlib.md5(content).hexdigest(),
        }

    return result
