import ast

def parse_dict_lines(texts):
    result = []

    for text in texts:
        for line in text.splitlines():
            try:
                value = ast.literal_eval(line)
            except (SyntaxError, ValueError) as exc:
                raise ValueError(f"Invalid dictionary literal: {line!r}") from exc

            if not isinstance(value, dict):
                raise ValueError(f"Line is not a dictionary literal: {line!r}")

            result.append(value)

    return result
```

Blank lines are treated as invalid, and an empty file contributes no dictionaries. `ast.literal_eval` parses Python literals without executing arbitrary code.

