    try:
        header = next(reader)
    except StopIteration:
        raise ValueError(f"Column {column_name!r} not found in header") from None

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found in header") from None

    return dict(Counter(row[column_index] for row in reader))
