import xml.etree.ElementTree as ET


def xml_to_tag_text_rows(xml_content):
    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML") from exc

    rows = []

    def visit(element):
        # Include text before and after child elements, but not their text.
        direct_text = (element.text or "") + "".join(
            child.tail or "" for child in element
        )
        rows.append([element.tag, direct_text])

        for child in element:
            visit(child)

    visit(root)
    return rows
```

This returns elements in document order and preserves whitespace in their direct text.

