import xml.etree.ElementTree as ET

def xml_to_tag_text_rows(xml_content):
    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML") from exc

    rows = []
    for element in root.iter():
        rows.append([element.tag, element.text or ""])
    return rows
```

`element.text` contains text directly inside the element; `root.iter()` visits elements in document order, including the root.

