import textwrap

def wrap_each_line(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    wrapped_lines = []
    for line in text.split("\n"):
        wrapped_lines.extend(
            textwrap.wrap(
                line,
                width=width,
                break_long_words=False,
                break_on_hyphens=False,
            ) or [""]
        )

    return "\n".join(wrapped_lines)
```

Each input line is wrapped independently. Long words remain unbroken, and blank lines are preserved.

