import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text):
    def reject_non_json_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(json_text, parse_constant=reject_non_json_constant)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Input is not valid JSON") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON input must be an object")

    result = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for {key!r} must be a base64-encoded string")

        try:
            decoded = base64.b64decode(value.encode("ascii"), validate=True).decode("utf-8")
        except (UnicodeEncodeError, binascii.Error, UnicodeDecodeError) as exc:
            raise ValueError(f"Value for {key!r} is not valid base64-encoded UTF-8") from exc

        result[key] = unicodedata.normalize("NFC", decoded)

    return result
```

